# Regulations for commercial pilots: 14 CFR 61.1, 61.23, 61.31, 61.56, 61.57, 61.123, 61.129, 61.133,
# 91.307, 91.313, 91.409, 119.1(e), 43.3; ACS areas I.A and I.B (FAA-S-ACS-7B). Key written first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Commercial limitations", "Your commercial certificate (airplane single-engine land) has no instrument rating. Which flight carrying passengers for hire may you make?",
      ["A daytime cross-country of 40 nautical miles",
       "A daytime cross-country of 70 nautical miles",
       "A 20-minute local flight after dark"],
      "Without an instrument rating in the same category and class, the certificate says carrying passengers for hire on cross-country flights of more than 50 nautical miles, or at night, is prohibited (14 CFR 61.133(b)(1)). A 40-mile daytime trip is within that limit."),
    S(1, 2, "Medical duration", "You are 35 and get a second-class medical certificate on March 10, 2026. Through what date may you use it for commercial pilot privileges?",
      ["March 31, 2027", "March 10, 2027", "September 30, 2026"],
      "For commercial privileges a second-class medical lasts to the end of the last day of the 12th month after the month of the exam (14 CFR 61.23(d)). The exam month is March 2026, so it runs through March 31, 2027."),
    S(1, 2, "Aeronautical experience", "Which night requirement must a commercial single-engine applicant log as solo or as the person performing the duties of pilot in command?",
      ["5 hours of night VFR with 10 takeoffs and 10 landings at an airport with an operating control tower",
       "3 hours of night VFR with 10 full-stop takeoffs and landings at any public airport",
       "5 hours of night VFR with 3 takeoffs and 3 landings to a full stop at any airport"],
      "14 CFR 61.129(a)(4)(ii) requires 5 hours in night VFR conditions with 10 takeoffs and 10 landings, each in the traffic pattern, at an airport with an operating control tower."),
    S(1, 2, "Part 119 exceptions", "A local business pays you to fly its advertising banner along a beach. Which certificate does this operation need beyond your commercial pilot certificate?",
      ["None, because banner towing is aerial work outside part 119",
       "A part 135 operating certificate held by the business",
       "A part 119 air carrier certificate held by you"],
      "Part 119 does not apply to aerial work such as banner towing, crop dusting, aerial photography or pipeline patrol (14 CFR 119.1(e)(4)). A commercial pilot may fly it under part 91."),
    S(1, 3, "100-hour inspection", "An airplane used for hire is due its 100-hour inspection at 1,250.0 tach hours. You reach a shop at 1,256.0 and the inspection is done there. When is the next 100-hour inspection due?",
      ["At 1,350.0 hours", "At 1,356.0 hours", "At 1,360.0 hours"],
      "The 100-hour limit may be exceeded by up to 10 hours to reach a place where the inspection can be done, but the excess counts toward the next 100 hours (14 CFR 91.409(b)). The next one is due 100 hours after 1,250.0, at 1,350.0."),
    S(1, 1, "Complex airplane", "Which airplane is a complex airplane under part 61?",
      ["Retractable gear, flaps and a controllable-pitch propeller",
       "Fixed gear, flaps and a 230-horsepower engine",
       "Retractable gear, no flaps and a fixed-pitch propeller"],
      "14 CFR 61.1 defines a complex airplane as one with retractable landing gear, flaps and a controllable-pitch propeller (including one with FADEC), or a seaplane with flaps and a controllable-pitch propeller. Engine power alone makes an airplane high performance, not complex."),
    S(1, 2, "Pressurized aircraft training", "You want to act as pilot in command of a pressurized airplane whose maximum operating altitude is FL300. What does part 61 require first?",
      ["Ground and flight training on high-altitude operations and a logbook endorsement",
       "A second-class medical and 50 hours in pressurized aircraft",
       "An instrument rating, a type rating for the airplane and a second-class medical"],
      "For a pressurized aircraft with a service ceiling or maximum operating altitude above 25,000 feet, 14 CFR 61.31(g) requires logged ground training on high-altitude topics, flight training in a pressurized aircraft or simulator, and an endorsement."),
    # ---------- Practice Test 2 ----------
    S(2, 1, "Eligibility", "What is the minimum age for a commercial pilot certificate?",
      ["18", "17", "21"],
      "14 CFR 61.123(a): a commercial pilot applicant must be at least 18 years old. The knowledge test itself may be taken earlier."),
    S(2, 2, "Aeronautical experience", "Of the 100 hours of pilot-in-command time required for a commercial single-engine rating, how much must be cross-country time?",
      ["50 hours, at least 10 of them in airplanes", "25 hours, all of them in airplanes", "10 hours, at least 5 of them at night"],
      "14 CFR 61.129(a)(2): 100 hours of PIC time including 50 hours in airplanes and 50 hours of cross-country flight, of which at least 10 must be in airplanes."),
    S(2, 2, "Aeronautical experience", "Which solo flight meets the long cross-country requirement for a commercial single-engine rating in the 48 contiguous states?",
      ["320 nm total, landings at three points, one of them 255 nm straight-line from the start",
       "300 nm total, landings at two points, one of them 250 nm straight-line from the start",
       "280 nm total, landings at three points, one of them 250 nm straight-line from the start"],
      "14 CFR 61.129(a)(4)(i): at least 300 nm total, landings at a minimum of three points, one of them at least 250 nm straight-line from the original departure point (150 nm in Hawaii)."),
    S(2, 3, "Aeronautical experience", "Your commercial practical test is on June 20. Which flights with an instructor count toward the 3 hours of test preparation in 61.129?",
      ["Flights on April 8 and May 30", "Flights on March 28 and May 30", "Flights on March 2 and April 8"],
      "The 3 hours must be within the preceding 2 calendar months from the month of the test (14 CFR 61.129(a)(3)(v)). For a June test that means April, May or June, so March flights do not count."),
    S(2, 3, "Medical duration", "You were 45 when you got a second-class medical in February 2025. In August 2026, what privileges does it support?",
      ["Private pilot privileges only", "Commercial pilot privileges", "None, because it has expired"],
      "Second-class privileges for commercial flying end after the 12th month (end of February 2026). For an applicant 40 or older it then serves as a third-class medical until the end of the 24th month, February 2027 (14 CFR 61.23(d))."),
    S(2, 2, "Holding out", "A commercial pilot advertises that he will fly anyone anywhere in his own airplane for a fee. What does this require?",
      ["A part 119 certificate, because it is common carriage offered to the public",
       "Only a commercial pilot certificate and a current second-class medical certificate",
       "Only a 100-hour inspection on the airplane"],
      "Holding out to carry persons or property for anyone who pays is common carriage. That needs an air carrier or operating certificate under part 119 (FAA AC 120-12A); a commercial pilot certificate alone does not allow it."),
    S(2, 2, "Special flight permit", "Your airplane's annual inspection has run out at a small field with no mechanic. How can it legally fly to a repair base?",
      ["Under a special flight permit issued by the FAA",
       "With a logbook entry by the pilot saying it is safe",
       "With passengers only if the flight is under 25 nm"],
      "An aircraft that does not meet airworthiness requirements but can fly safely may be ferried to a repair base under a special flight permit (14 CFR 21.197), obtained through the local Flight Standards office."),
    # ---------- Drill only ----------
    S(0, 1, "High-performance airplane", "Which airplane needs a high-performance endorsement before you act as pilot in command?",
      ["A single-engine airplane with a 230-horsepower engine",
       "A twin with two 180-horsepower engines",
       "A single-engine airplane with a 200-horsepower engine"],
      "A high-performance airplane has an engine of more than 200 horsepower (14 CFR 61.31(f)). The threshold is per engine, so two 180-horsepower engines and one 200-horsepower engine do not qualify."),
    S(0, 2, "Tailwheel endorsement", "Which training does 61.31 require before you act as pilot in command of a tailwheel airplane?",
      ["Normal and crosswind takeoffs and landings, wheel landings and go-arounds",
       "Spins in both directions and recovery from unusual attitudes",
       "Short-field and soft-field landings in a complex airplane"],
      "14 CFR 61.31(i) requires flight training in a tailwheel airplane including normal and crosswind takeoffs and landings, wheel landings (unless the manufacturer recommends against them) and go-arounds, plus an endorsement."),
    S(0, 2, "Flight review", "You passed your commercial pilot practical test 10 months ago. When must you complete a flight review?",
      ["Within 24 calendar months of the practical test", "Within 12 calendar months of the practical test", "Before your next flight carrying passengers for hire"],
      "Passing a practical test for a certificate or rating counts as a flight review (14 CFR 61.56(d)), so the next one is due by the end of the 24th calendar month after it."),
    S(0, 2, "Class ratings", "Your commercial certificate has only an airplane single-engine land rating. May you act as pilot in command of a twin for hire?",
      ["No, you need a multiengine class rating", "Yes, with a high-performance endorsement", "Yes, if you have 10 hours of multiengine dual"],
      "To act as PIC for compensation or hire, a pilot must hold the category and class rating for the aircraft (14 CFR 61.31(d)). A twin needs an airplane multiengine rating."),
    S(0, 2, "Parachutes", "With a paying passenger on board, which maneuver requires everyone to wear an approved parachute?",
      ["A turn with a 70 degree bank", "A turn with a 50 degree bank", "A climb at 25 degrees nose-up"],
      "14 CFR 91.307(c): with any occupant other than a crewmember, parachutes are required for intentional maneuvers exceeding 60 degrees of bank or 30 degrees nose-up or nose-down pitch (unless it is flight training for a certificate or rating)."),
    S(0, 2, "Kinds of operation", "What does a Kinds of Operations Equipment List (KOEL) show?",
      ["The equipment that must work for each kind of operation, such as day VFR, night VFR or IFR",
       "The equipment that may stay inoperative under an approved minimum equipment list",
       "The equipment that must be checked during an annual inspection"],
      "Many airplane flight manuals contain a KOEL listing the equipment required for each kind of operation the airplane is approved for (ACS CA.I.B.K3c, PHAK chapter 9)."),
    S(0, 2, "Restricted category", "An airplane holds a special airworthiness certificate in the restricted category for agricultural work. What may it NOT do?",
      ["Carry persons or property for hire outside its special purpose",
       "Spray crops for compensation",
       "Fly to and from the work site with its required crew"],
      "14 CFR 91.313 bars carrying persons or property for compensation or hire in a restricted-category aircraft, except as part of the special purpose operation for which it was certificated."),
    S(0, 2, "Preventive maintenance", "May a commercial pilot do preventive maintenance, such as changing an oil filter, on an airplane used in part 135 charter?",
      ["No, unless done under an approved program with FAA authorization",
       "Yes, if the pilot holds a second-class medical",
       "Yes, as long as the pilot owns the airplane and logs the work"],
      "The pilot preventive maintenance privilege in 14 CFR 43.3(g) covers aircraft the pilot owns or operates that are not used under parts 121, 129 or 135. Part 135 aircraft need a mechanic or an approved procedure."),
    S(0, 3, "100-hour inspection", "A student brings her own airplane and pays you only for instruction. Must the airplane have a 100-hour inspection?",
      ["No, because the airplane is not provided by the person giving the instruction",
       "Yes, because any instruction given for hire needs a 100-hour inspection",
       "Yes, because any airplane used for training needs one"],
      "14 CFR 91.409(b) requires the 100-hour inspection for an aircraft carrying any person for hire, or for flight instruction for hire in an aircraft provided by the person giving the instruction."),
    S(0, 3, "100-hour inspection", "An airplane used for hire gets an annual inspection at 1,200 tach hours. When is the next 100-hour inspection due?",
      ["At 1,300 hours", "At 1,200 hours plus 12 calendar months", "At 1,250 hours"],
      "An annual inspection also meets the 100-hour requirement (14 CFR 91.409(b)), so the 100-hour clock restarts at 1,200 and the next one is due at 1,300."),
    S(0, 2, "Part 119 exceptions", "Under 119.1(e), when may you carry skydivers for hire without a part 119 certificate?",
      ["On a nonstop flight within 25 statute miles of the takeoff airport",
       "On any flight under 50 nautical miles in daylight",
       "Only when the jump aircraft has 9 passenger seats or fewer and flies in daylight"],
      "14 CFR 119.1(e)(6) excepts nonstop flights within a 25-statute-mile radius of the airport of takeoff carrying persons for intentional parachute operations."),
    S(0, 2, "Aeronautical experience", "Which airplane can be used for the 10 hours of training in 61.129(a)(3)(ii) for a single-engine commercial rating?",
      ["A complex airplane, a turbine-powered airplane or a technically advanced airplane",
       "Only a complex airplane with retractable gear, flaps and a controllable-pitch propeller",
       "Any airplane with an engine of more than 200 horsepower"],
      "Since 2018 the 10 hours may be in a complex airplane, a turbine-powered airplane or a technically advanced airplane (TAA), or any combination, appropriate to land or sea (14 CFR 61.129(a)(3)(ii))."),
    S(0, 2, "Technically advanced airplane", "For commercial training, what equipment makes an airplane a technically advanced airplane (TAA)?",
      ["A primary flight display, a multifunction display with GPS moving map, and a two-axis autopilot",
       "Retractable gear, flaps and a controllable-pitch propeller",
       "A turbocharged engine, a glass primary flight display and an ADS-B In traffic display"],
      "14 CFR 61.129(j): an electronically advanced avionics system with a PFD, an MFD including at least a moving map using GPS, and a two-axis autopilot integrated with the navigation and heading guidance."),
    S(0, 2, "Aeronautical experience", "How much of the 10 hours of commercial instrument training must be in a single-engine airplane for a single-engine rating?",
      ["5 hours", "10 hours", "3 hours"],
      "14 CFR 61.129(a)(3)(i): 10 hours of instrument training with a view-limiting device, 5 of which must be in a single-engine airplane."),
    S(0, 2, "Medical class", "You will fly cargo for hire as a commercial pilot. What is the lowest class of medical certificate you need?",
      ["Second class", "Third class", "First class"],
      "Commercial pilot privileges need at least a second-class medical (14 CFR 61.23(a)(2)). A first-class medical is needed only for airline transport pilot privileges."),
]
